1	/* The Build page's own rules: what the design system can't say. */
2	@scope (.build) {
3	  /* A page's name on its card, and a story's title: headings at a section's
4	     size, not a card's small label. */
5	  .page-title { font-size: var(--text-md); }
6	  .story-title { font-size: var(--text-lg); }
7	}
8	
9	/* A build session: the design page's frame (workspace.css lays out the chat
10	   and the header), with the check where the design surface was. It takes
11	   the room the chat leaves, never wrapping; stacked under it when narrow,
12	   sharing the height. */
13	@scope (.build-session) {
14	  .workspace > .check { flex: 1 1 0; min-inline-size: 0; min-block-size: 0; }
15	  .check > .panel-body { flex: 1; min-block-size: 0; overflow: auto; }
16	  @container (width < 52rem) {
17	    .workspace > .check { flex: 3 1 0; }
18	  }
19	
20	  /* A screen of the check: its picture, at the page's shape, on the sunken
21	     ground the design surface uses. Marked, the differences show. */
22	  .shot-title { font-size: var(--text-md); }
23	  .shot {
24	    display: grid; place-items: center; aspect-ratio: 16 / 10; margin: 0;
25	    background: var(--surface-sunken); border: var(--border-width) solid var(--border); border-radius: var(--radius-md);
26	  }
27	  .shot.marked { border-color: var(--warn); }
28	}
